UPDATE public_submission_delivery_state SET status = CASE WHEN ? = 'accepted' THEN 'accepted' WHEN ? = 'retryable' AND attempt_count < 5 AND unixepoch() + ? < (SELECT task.created_at + 86400 FROM public_submission_delivery_outbox AS task WHERE task.task_id = public_submission_delivery_state.task_id) AND unixepoch() + ? < (SELECT source.expires_at FROM public_submission_delivery_outbox AS task JOIN public_form_submissions AS source ON source.submission_id = task.source_submission_id WHERE task.task_id = public_submission_delivery_state.task_id) THEN 'pending' ELSE 'failed' END, next_attempt_at = CASE WHEN ? = 'retryable' AND attempt_count < 5 AND unixepoch() + ? < (SELECT task.created_at + 86400 FROM public_submission_delivery_outbox AS task WHERE task.task_id = public_submission_delivery_state.task_id) AND unixepoch() + ? < (SELECT source.expires_at FROM public_submission_delivery_outbox AS task JOIN public_form_submissions AS source ON source.submission_id = task.source_submission_id WHERE task.task_id = public_submission_delivery_state.task_id) THEN unixepoch() + ? ELSE next_attempt_at END, last_outcome_code = CASE WHEN ? = 'retryable' AND attempt_count >= 5 THEN 'retry_exhausted' WHEN ? = 'retryable' AND (unixepoch() + ? >= COALESCE((SELECT task.created_at + 86400 FROM public_submission_delivery_outbox AS task WHERE task.task_id = public_submission_delivery_state.task_id), 0) OR unixepoch() + ? >= COALESCE((SELECT source.expires_at FROM public_submission_delivery_outbox AS task JOIN public_form_submissions AS source ON source.submission_id = task.source_submission_id WHERE task.task_id = public_submission_delivery_state.task_id), 0)) THEN 'delivery_window_elapsed' ELSE ? END, last_http_status = ?, lease_token = NULL, lease_expires_at = NULL, completed_at = CASE WHEN ? = 'accepted' THEN unixepoch() WHEN ? = 'retryable' AND attempt_count < 5 AND unixepoch() + ? < (SELECT task.created_at + 86400 FROM public_submission_delivery_outbox AS task WHERE task.task_id = public_submission_delivery_state.task_id) AND unixepoch() + ? < (SELECT source.expires_at FROM public_submission_delivery_outbox AS task JOIN public_form_submissions AS source ON source.submission_id = task.source_submission_id WHERE task.task_id = public_submission_delivery_state.task_id) THEN NULL ELSE unixepoch() END, updated_at = unixepoch() WHERE task_id = ? AND status = 'leased' AND lease_token = ? AND lease_expires_at > unixepoch() AND attempt_count = ? AND last_attempt_at = ? RETURNING task_id
